    static bool Near(float a,float b){return Math.Abs(a-b)<.00001f;}
    sealed class Query:IInteractionQuery{public bool Visible=true;public bool HasLineOfSight(string a,string b,Float3 c,Float3 d,float r){return Visible;}}
    static HandlingInput Input(bool fire=false,bool grip=false,Float3 local=new Float3(),bool left=false){return new HandlingInput{Enabled=true,PrimaryTracked=true,SupportTracked=true,Trigger=fire,Grip=grip,SupportLocal=local,ForegripDistance=1,LeftHanded=left};}
    static LocalRifleSandbox Gun(SourceRifleDefinition definition,R23RifleReserve reserve){return new LocalRifleSandbox(new string[0],new Query(),definition,reserve,"checks/"+definition.Id);}
    static void PhysicalReload(LocalRifleSandbox gun,SourceRifleDefinition profile,bool left){if(gun.Snapshot.Phase==ReloadPhase.Ready)gun.Step(0,Input(false,false,profile.Offer,left),true,false);gun.Step(.12f,Input(false,false,profile.Offer,left),false,false);gun.Step(0,Input(false,true,profile.Offer,left),false,false);Check(gun.Snapshot.Phase==ReloadPhase.HeldMagazine,profile.Id+" actual fresh support grip takes real magazine");gun.Step(0,Input(false,true,profile.Insert,left),false,false);Check(gun.Snapshot.Phase==ReloadPhase.NeedsRack&&gun.Snapshot.Seated==profile.Capacity,profile.Id+" upward source stroke seats native magazine");gun.Step(0,Input(false,false,profile.Charging,left),false,false);gun.Step(0,Input(false,true,profile.Charging,left),false,false);gun.Step(.12f,Input(false,true,new Float3(profile.Charging.X,profile.Charging.Y,profile.Charging.Z-.076f),left),false,false);Check(gun.Snapshot.Phase==ReloadPhase.Ready&&gun.Snapshot.Loaded==profile.Capacity,profile.Id+" source rearward charging stroke chambers real native rounds");}
    static int Main(){try{
        var cx=SourceRifleDefinition.Cx4;var px=SourceRifleDefinition.Px4;
        Check(cx.Id=="cx4"&&cx.Capacity==25&&Near(cx.Interval,1f/6)&&!cx.SemiAutomatic&&cx.AmmoFamily=="rifle"&&cx.BodyDamage==19&&cx.HeadDamage==23,"actual first-rarity CX4 capacity25 auto6rps and latest0991 damage19/23");
        Check(px.Id=="px4"&&px.Capacity==16&&px.Interval==.21f&&px.SemiAutomatic&&px.AmmoFamily=="pistol"&&px.BodyDamage==30&&px.HeadDamage==45,"actual first-rarity PX4 capacity16 semi.21s and latest0991 damage30/45");
        Check(cx.ModelScale==.855f&&px.ModelScale==.7f&&px.Pistol&&px.SupportPoint.Y==-.065f&&px.SupportPoint.Z==.095f,"source distinct visual scales and cupped pistol support datum");
        var reserve=new R23RifleReserve();var auto=Gun(cx,reserve);auto.SuspendControls();Check(!auto.Step(.25f,Input(true),false,false),"new CX4 instance requires neutral trigger after custody suspension");auto.Step(0,Input(),false,false);Check(auto.Step(0,Input(true),false,false)&&auto.Snapshot.Loaded==24,"real CX4 accepted first shot debits one native round");Check(!auto.Step(.15f,Input(true),false,false),"CX4 automatic cadence refuses too-early held-trigger shot");Check(auto.Step(1f/60,Input(true),false,false)&&auto.Snapshot.Loaded==23,"CX4 exact1/6 automatic interval accepts continued held trigger");
        int accepted=2;for(int i=0;i<23;i++)if(auto.Step(1f/6,Input(true),false,false))accepted++;Check(accepted==25&&auto.Snapshot.Loaded==0&&auto.Snapshot.Phase==ReloadPhase.NeedsMagazine&&reserve.Available==2400,"CX4 empties25 actual rounds then enters existing source magazine flow without reserve shadow debit");PhysicalReload(auto,cx,false);Check(reserve.Available==2375&&auto.LoadedRounds==25,"CX4 actual physical reload debits shared rifle pool25 once");
        Check(Near(auto.Snapshot.CooldownSeconds,.12f),"CX4 completed source reload retains actual staged.12s cooldown");
        var pistolPool=new R23RifleReserve(1200);var pistol=Gun(px,pistolPool);pistol.SuspendControls();pistol.Step(0,Input(),false,false);Check(pistol.Step(0,Input(true),false,false)&&pistol.LoadedRounds==15,"PX4 real accepted shot consumes one actual pistol round");Check(!pistol.Step(.25f,Input(true),false,false)&&pistol.LoadedRounds==15,"PX4 held trigger never becomes automatic after cooldown");pistol.Step(0,Input(),false,false);Check(pistol.Step(0,Input(true),false,false),"PX4 trigger release rearms source semi without SPR-specific.2 hysteresis");PhysicalReload(pistol,px,true);Check(pistolPool.Available==1198&&pistol.LoadedRounds==16,"PX4 left-primary reload refunds remaining rounds then debits16 from actual finite pool");
        pistol.Step(.25f,Input(),false,false);Check(pistol.Step(.25f,Input(true),false,false)&&Near(pistol.Snapshot.CooldownSeconds,.21f),"PX4 late re-press starts full source.21 interval rather than generic auto-rifle overrun credit");
        var cup=Input(false,true);cup.ForegripDistance=.1f;pistol.Step(0,Input(false,false),false,false);pistol.Step(.21f,cup,false,false);Check(pistol.Snapshot.Supported&&pistol.Snapshot.ClaimsSupport,"PX4 real cupped support owns offhand and stabilizes native shot profile");cup.Trigger=true;Check(pistol.Step(0,cup,false,false),"supported PX4 can fire through native source owner");
        int rounds=pistol.LoadedRounds;float cooldown=pistol.Snapshot.CooldownSeconds;pistol.Step(.25f,Input(true),false,true);Check(pistol.LoadedRounds==rounds&&pistol.Snapshot.CooldownSeconds==cooldown&&!pistol.Step(.25f,Input(true),false,false),"PX4 pause freezes actual cooldown and held trigger cannot fire on resume");
        var blocked=Input(true);blocked.PrimaryTracked=false;Check(!auto.Step(.25f,blocked,false,false),"CX4 primary tracking loss cannot consume ammunition");blocked=Input(true);blocked.PrimaryClimbing=true;Check(!auto.Step(.25f,blocked,false,false),"CX4 primary climb reservation gates accepted fire");
        var physicalRound=new R23RoundState(new string[0],new Query(),true);physicalRound.SelectWeapon("px4");physicalRound.Step(0,Input(),false,false);physicalRound.Step(0,Input(),true,false);physicalRound.Step(.12f,Input(),true,false);Check(physicalRound.ActiveSnapshot.Phase==ReloadPhase.NeedsMagazine,"actual production VR right-click opens PX4 and cannot auto-insert on another click");physicalRound.Step(0,Input(false,false,px.Offer),false,false);physicalRound.Step(0,Input(false,true,px.Offer),false,false);physicalRound.Step(0,Input(false,true,px.Insert),false,false);Check(physicalRound.ActiveSnapshot.Phase==ReloadPhase.NeedsRack&&physicalRound.ActiveLoaded==16,"actual production PX4 support stroke seats native ammunition after VR opening");physicalRound.Step(0,Input(false,false,px.Charging),false,false);physicalRound.Step(0,Input(false,true,px.Charging),false,false);physicalRound.Step(.12f,Input(false,true,new Float3(px.Charging.X,px.Charging.Y,px.Charging.Z-.076f)),false,false);Check(physicalRound.ActiveSnapshot.Phase==ReloadPhase.Ready&&physicalRound.ActiveReserve==1200,"actual production PX4 released-grip slide pull charges without refill");
        var query=new Query();var round=new R23RoundState(new[]{"target"},query,true);round.EnsureMagnumState("shared/magnum");round.SelectWeapon("px4");round.Step(.21f,Input(),false,false);round.Step(0,Input(true),false,false);Check(round.Hit("target",new Float3(),new Float3(0,0,150),false,"px4")&&round.LastTargetDamage("target")==30,"production PX4 applies source30 damage through real HealthService at150m");round.Step(.21f,Input(),false,false);round.Step(0,Input(true),false,false);Check(round.Hit("target",new Float3(),new Float3(0,0,2),true,"px4")&&round.LastTargetDamage("target")==45,"production PX4 applies listed45 head damage without invented multiplier");
        var desktop=Input();desktop.Desktop=true;round.Step(0,desktop,true,false);round.Step(.12f,desktop,true,false);round.Step(.12f,desktop,true,false);Check(round.ReadReserve("px4")==1198&&round.ReadReserve("magnum")==1198&&round.ReadReserve("cx4")==2400,"PX4 and Magnum share true pistol1200 pool, separate from rifle reserve");
        string identity=round.WeaponInstanceId("px4");int loaded=round.ActiveLoaded;round.SelectWeapon("cx4");round.SelectWeapon("px4");Check(round.WeaponInstanceId("px4")==identity&&round.ActiveLoaded==loaded&&round.ActiveReserve==1198,"source selection retains exact PX4 instance/magazine/shared reserve without grants");
        round.SelectWeapon("cx4");round.Step(.2f,Input(),false,false);round.Step(0,Input(true),false,false);Check(round.Hit("target",new Float3(),new Float3(0,0,150),false,"cx4")&&round.LastTargetDamage("target")==19,"production CX4 source damage19 uses real accepted native shot");round.Step(0,Input(),true,false);Check(round.ReadReserve("mk18")==2424&&round.ReadReserve("akm")==2424&&round.ReadReserve("cx4")==2424&&round.ReadReserve("spr")==2400,"CX4 source eject refund shares rifle pool with MK18/AKM, sniper remains separate");
        var feedback=new R23WeaponFeedbackState("cx4");feedback.AcceptedShot(1,false);Check(Near(feedback.PitchRadians,.351547f*(float)Math.PI/180*1.25f)&&Near(feedback.YawRadians,.044536f*(float)Math.PI/180*1.25f),"CX4 uses actual observed source time0 output, not substituted MK18 curve");feedback.Advance(.02778f);Check(Near(feedback.PitchRadians,.706919f*(float)Math.PI/180*1.25f),"CX4 source observed recoil interpolates shipped time samples");feedback.ClearPresentation();Check(feedback.PitchRadians==0&&feedback.Distance==0,"CX4 holster/focus clears observed output without weapon state mutation");
        var pulse=new R23WeaponFeedbackState("px4");pulse.AcceptedShot(1,false);Check(Near(pulse.Distance,.0312f*1.25f),"PX4 source pistol reduction applies.0312m accepted-shot visual kick");pulse.Advance(.0475f);Check(Near(pulse.SlideTravel,.035f),"PX4 actual source95ms slide cycle reaches35mm halfway");pulse.Advance(.0495f);Check(Near(pulse.PitchRadians,6.655f*(float)Math.PI/180*1.25f)&&pulse.SlideTravel==0,"PX4 source6.655degree signed pulse peaks97ms while slide closes");Check(Near(R23WeaponFeedbackState.Px4Pulse(.226f),0)&&Near(R23WeaponFeedbackState.Px4Pulse(.278f),-.18f)&&R23WeaponFeedbackState.Px4Pulse(.45f)==0,"PX4 exact source226/278/450ms zero/undershoot/end pulse");
        float score,nearScore;Check(R23WeaponPickupRules.TryScore(.35f,-1,true,true,out nearScore)&&Near(nearScore,2),"source auto proximity35cm accepts any controller angle");Check(R23WeaponPickupRules.TryScore(2,1,true,true,out score)&&Near(score,.95f),"source aimed corrected-grip reach accepts exactly2m");Check(!R23WeaponPickupRules.TryScore(2.0001f,1,true,true,out score)&&!R23WeaponPickupRules.TryScore(.36f,.94f,true,true,out score),"source remote reach and strict>.94 alignment boundaries reject");Check(R23WeaponPickupRules.TryScore(.5f,.95f,true,true,out score)&&nearScore>score,"source nearby pickup scores above farther aligned pickup");Check(!R23WeaponPickupRules.TryScore(1,1,false,true,out score)&&!R23WeaponPickupRules.TryScore(1,1,true,false,out score),"head-to-hand and hand-to-real-center occlusion independently deny acquisition");Check(R23WeaponPickupRules.CatalogIndex("cx4")==0&&R23WeaponPickupRules.CatalogIndex("px4")==2&&R23WeaponPickupRules.CatalogIndex("mk18")==3&&R23WeaponPickupRules.CatalogIndex("spr")==13&&R23WeaponPickupRules.CatalogIndex("akm")==21,"equal-score ties use actual original catalog identities");
        Console.WriteLine(count+" focused CX4/PX4 source-owner/pickup cases passed");return 0;
    }catch(Exception error){Console.WriteLine(error);return 1;}}
}
